@namespace sv_16edc26760db4e51b1b6e2a10bedb72b.Components.Pages.Settings
@using sv_16edc26760db4e51b1b6e2a10bedb72b.Services

<h5 class="mb-3">Active Sessions</h5>

@if (Sessions is null || Sessions.Count == 0)
{
    <p class="text-muted">No active sessions.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-hover">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                @if (_confirmingId == session.Id)
                                {
                                    <span class="me-2 text-danger small">Revoke this session?</span>
                                    <button class="btn btn-sm btn-danger me-1" @onclick="() => ConfirmRevoke(session.Id)">Yes</button>
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="CancelRevoke">No</button>
                                }
                                else
                                {
                                    <button class="btn btn-sm btn-outline-danger" @onclick="() => RequestRevoke(session.Id)">Revoke</button>
                                }
                            }
                            else
                            {
                                <span class="badge bg-success">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingId;

    private void RequestRevoke(string sessionId) => _confirmingId = sessionId;
    private void CancelRevoke() => _confirmingId = null;

    private async Task ConfirmRevoke(string sessionId)
    {
        _confirmingId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

