@namespace sv_16edc26760db4e51b1b6e2a10bedb72b.Components.Pages.Settings
@using sv_16edc26760db4e51b1b6e2a10bedb72b.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (_settings is null)
    {
        <p class="text-muted">Loading...</p>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <small class="text-muted">
                        @if (_settings.TwoFactorEnabled)
                        {
                            <span class="text-success"><i class="bi bi-check-circle-fill me-1"></i>Enabled</span>
                        }
                        else
                        {
                            <span class="text-warning"><i class="bi bi-exclamation-circle-fill me-1"></i>Disabled</span>
                        }
                    </small>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@_settings.TwoFactorEnabled" disabled />
                </div>
            </div>
        </div>

        @if (_settings.LastPasswordChange.HasValue)
        {
            <p class="text-muted small mb-4">
                <i class="bi bi-clock me-1"></i>Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        <ActiveSessionsTable Sessions="_settings.Sessions.ToList()" CurrentSessionId="sess-1" OnRevoke="HandleRevoke" />
    }
</div>

@code {
    private SecuritySettings? _settings;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevoke(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }
}

