@namespace sv_16edc26760db4e51b1b6e2a10bedb72b.Components.Pages.Settings
@using sv_16edc26760db4e51b1b6e2a10bedb72b.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="mb-4">Appearance</h4>

    @if (_settings is null)
    {
        <p class="text-muted">Loading...</p>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="mb-4">
                    <label class="form-label fw-bold">Theme</label>
                    <div>
                        @foreach (var theme in _themes)
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                       value="@theme" checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="mb-4">
                    <label class="form-label fw-bold">Font Size</label>
                    <div>
                        @foreach (var size in _fontSizes)
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                       value="@size" checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="mb-4">
                    <label class="form-label fw-bold">Language</label>
                    <select class="form-select" style="max-width:250px;" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
                @if (!string.IsNullOrEmpty(_successMessage))
                {
                    <span class="text-success ms-3">@_successMessage</span>
                }
            </div>

            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <small class="fw-bold">Live Preview</small>
                    </div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h6>Sample Heading</h6>
                        <p class="mb-2">This is how your content will look with the selected appearance settings.</p>
                        <button class="btn btn-sm btn-primary">Sample Button</button>
                        <span class="badge bg-secondary ms-2">Badge</span>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private string? _successMessage;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_theme == "Dark") classes.Add("bg-dark text-light");
        if (_compactMode) classes.Add("p-2");
        else classes.Add("p-3");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var size = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size:{size};transition:all 0.3s ease;";
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;
        _successMessage = "Appearance saved!";
    }
}

